const D = params.size;
const R = D * 0.5;
const wallH = R * 0.16;
const domeH = R * 0.92;
const snow = { preset: 'snow', color: '#e8f2f5', roughness: 0.92, flatShading: true };
const snowLight = { preset: 'snow', color: '#f5fbfc', roughness: 0.9, flatShading: true };
const seam = { preset: 'snow', color: '#9fb9c2', roughness: 1, flatShading: true };
const shadow = { preset: 'concrete', color: '#26373e', roughness: 1 };

const profile = [[0,0],[R,0],[R,wallH]];
for (let i = 1; i <= 8; i++) {
  const y = wallH + domeH * i / 8;
  const t = (y - wallH) / domeH;
  const rr = R * Math.sqrt(Math.max(0, 1 - t * t));
  profile.push([rr,y]);
}
profile.push([0,wallH + domeH]);
const dome = api.lathe(profile, 32);
dome.vertexColor((x,y,z) => {
  const n = api.noise3(x * 3.1, y * 3.1, z * 3.1);
  return api.mix('#dcebee', '#ffffff', 0.48 + n * 0.14);
});
api.add(dome, snow);

const courses = 7;
for (let j = 1; j <= courses; j++) {
  const y = wallH + domeH * j / 8;
  const t = (y - wallH) / domeH;
  const rr = R * Math.sqrt(Math.max(0.01, 1 - t * t));
  api.add(api.torus(rr * 1.006, R * 0.012).rotate(90,0,0).translate(0,y,0), seam);
  const blocks = Math.max(6, Math.round(22 * rr / R));
  const phase = (j % 2) * Math.PI / blocks;
  for (let k = 0; k < blocks; k++) {
    const a = k * Math.PI * 2 / blocks + phase;
    const x = Math.sin(a) * rr * 1.012;
    const z = Math.cos(a) * rr * 1.012;
    const joint = api.box(R * 0.014, domeH / 8 * 0.76, R * 0.032).rotate(0,a * 180 / Math.PI,0).translate(x,y - domeH / 16,z);
    api.add(joint, seam);
  }
}
api.add(api.torus(R * 0.997, R * 0.014).rotate(90,0,0).translate(0,wallH,0), seam);

const iw = R * 0.46;
const ih = R * 0.62;
const tunnelL = R * 0.68;
const block = R * 0.16;
const frontZ = R + tunnelL;
const backZ = R * 0.72;
const depth = frontZ - backZ;
api.add(api.box(block, ih * 0.72, depth).translate(-iw * 0.5 - block * 0.48, ih * 0.36, (frontZ + backZ) * 0.5), snowLight);
api.add(api.box(block, ih * 0.72, depth).translate(iw * 0.5 + block * 0.48, ih * 0.36, (frontZ + backZ) * 0.5), snowLight);

const archR = iw * 0.5 + block * 0.5;
const archY = ih * 0.68;
for (let k = 0; k < 7; k++) {
  const a = Math.PI * k / 6;
  const x = Math.cos(a) * archR;
  const y = archY + Math.sin(a) * archR;
  const cap = api.box(block * 0.94, block * 0.88, depth).rotate(0,0,a * 180 / Math.PI - 90).translate(x,y,(frontZ + backZ) * 0.5);
  api.add(cap, k % 2 === 0 ? snow : snowLight);
}

const openingShape = [[-iw * 0.5,0],[iw * 0.5,0],[iw * 0.5,ih * 0.68]];
for (let k = 0; k <= 8; k++) {
  const a = k * Math.PI / 8;
  openingShape.push([Math.cos(a) * iw * 0.5, ih * 0.68 + Math.sin(a) * iw * 0.5]);
}
openingShape.push([-iw * 0.5,ih * 0.68]);
api.add(api.extrude(openingShape,R * 0.025).translate(0,0,frontZ + R * 0.018), shadow);

for (let side = -1; side <= 1; side += 2) {
  for (let j = 1; j < 4; j++) {
    api.add(api.box(block * 1.02,R * 0.012,R * 0.035).translate(side * (iw * 0.5 + block * 0.48),j * ih * 0.18,frontZ + R * 0.025),seam);
  }
}
for (let j = 0; j < 3; j++) {
  const z = backZ + depth * (j + 1) / 4;
  api.add(api.box(iw + block * 1.9,R * 0.012,R * 0.035).translate(0,ih * 0.03,z),seam);
}

api.collider({ kind: 'cylinder', radius: R, halfHeight: (wallH + domeH) * 0.5, offset: [0,(wallH + domeH) * 0.5,0] });
api.collider({ kind: 'box', halfExtents: [iw * 0.5 + block, ih * 0.52, depth * 0.5], offset: [0,ih * 0.52,(frontZ + backZ) * 0.5] });
return api.build();
